import React, { useState } from 'react';
import MapView from './components/MapView';
import ListView from './components/ListView';
import events from './data/events';
import './index.css';

const NAV_ITEMS = [
  { id: 'map', label: 'Carte' },
  { id: 'list', label: 'Événements' },
  { id: 'about', label: 'À propos' },
];

function About() {
  return (
    <div style={{ maxWidth: 640, margin: '64px auto', padding: '0 24px' }}>
      <h1 style={{ fontSize: 56, marginBottom: 24, lineHeight: 1 }}>À propos</h1>
      <p style={{ fontSize: 15, lineHeight: 1.8, color: 'var(--text-secondary)', fontWeight: 300 }}>
        Mujawara — du mot arabe <em>مجاورة</em>, "voisinage" — est une cartographie
        des événements politiques et militants à travers le monde. Un outil pour
        connecter les luttes, visualiser les résistances, tisser l'internationalisme.
      </p>
    </div>
  );
}

export default function App() {
  const [view, setView] = useState('map');

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      <header style={{
        height: 60,
        background: 'var(--surface)',
        borderBottom: '1px solid var(--border)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        padding: '0 32px',
        position: 'sticky',
        top: 0,
        zIndex: 1000,
      }}>
        {/* Logo */}
        <button
          onClick={() => setView('map')}
          style={{
            background: 'none', border: 'none', cursor: 'pointer', padding: 0,
            fontFamily: 'var(--font-title)',
            fontWeight: 800,
            fontStyle: 'italic',
            fontSize: 30,
            color: 'var(--text-primary)',
            letterSpacing: '-0.5px',
            lineHeight: 1,
          }}
        >
          MUJAWARA
        </button>

        {/* Nav */}
        <nav style={{ display: 'flex', gap: 4 }}>
          {NAV_ITEMS.map(({ id, label }) => (
            <button
              key={id}
              onClick={() => setView(id)}
              style={{
                background: 'none',
                border: 'none',
                cursor: 'pointer',
                fontFamily: 'var(--font-body)',
                fontSize: 13,
                fontWeight: view === id ? 500 : 400,
                color: view === id ? 'var(--text-primary)' : 'var(--text-muted)',
                padding: '6px 14px',
                borderRadius: 'var(--radius-sm)',
                background: view === id ? 'var(--bg)' : 'transparent',
                transition: 'all 0.15s',
                borderBottom: view === id ? '1.5px solid var(--text-primary)' : '1.5px solid transparent',
              }}
            >
              {label}
            </button>
          ))}
        </nav>

        {/* Counter */}
        <div style={{
          fontSize: 12,
          color: 'var(--text-muted)',
          fontFamily: 'var(--font-body)',
          fontWeight: 300,
        }}>
          {events.length} événements · {new Set(events.map(e => e.country)).size} pays
        </div>
      </header>

      <main style={{ flex: 1 }}>
        {view === 'map' && <MapView events={events} />}
        {view === 'list' && <ListView events={events} />}
        {view === 'about' && <About />}
      </main>
    </div>
  );
}
